Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-25jul852peakindexinamountainarray":{"key":"topic-25jul852peakindexinamountainarray","number":null,"title":"25 JUL 852 Peak Index in a Mountain Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-JUL 852 Peak Index in a Mountain Array.py","code":"class Solution:\n    def peakIndexInMountainArray(self, A: List[int]) -> int:\n        low = 0\n        high = len(A) - 1\n        while low < high:\n            mid = low + ((high - low) >> 1)\n            if A[mid] < A[mid + 1]:\n                low = mid + 1\n            else:\n                high = mid\n        return low","hash":"ed82d6a799eee3f75db95fa44770e145c1eb62cba47abd5058a52510ea7176df","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/25-JUL 852 Peak Index in a Mountain Array.py"}]}],"sources":["solutions"]},"topic-25jun1575countallpossibleroutes":{"key":"topic-25jun1575countallpossibleroutes","number":null,"title":"25 JUN 1575 Count All Possible Routes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-JUN 1575 Count All Possible Routes.py","code":"class Solution:\n    def countRoutes(self, locations: List[int], start: int, finish: int, fuel: int) -> int:\n        locationsLen, modulus = len(locations), 10 ** 9 + 7\n        dp = [[-1] * (fuel + 1) for _ in range(locationsLen)]\n        \n        def dfs(city, fuel):\n            if fuel < 0:\n                return 0\n            if dp[city][fuel] != -1:\n                return dp[city][fuel]\n            result = 0\n            if city == finish:\n                result = 1\n            for i in range(locationsLen):\n                if i != city and fuel - abs(locations[i] - locations[city]) >= 0:\n                    result += dfs(i, fuel - abs(locations[i] - locations[city])) % modulus\n            dp[city][fuel] = result\n            return result\n            \n        return dfs(start, fuel) % modulus","hash":"bfcd80b8936b53b916d061af0240010a65636dbfc8876386b26683aff1a9a2e6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/25-JUN 1575 Count All Possible Routes.py"}]}],"sources":["solutions"]},"topic-25may837new21game":{"key":"topic-25may837new21game","number":null,"title":"25 MAY 837 New 21 Game","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-MAY 837 New 21 Game.py","code":"class Solution:\n    def new21Game(self, n: int, k: int, maxPts: int) -> float:\n        dp = [0] * (n + 1)\n        dp[0] = 1\n        s = 1 if k > 0 else 0\n        for i in range(1, n + 1):\n            dp[i] = s / maxPts\n            if i < k:\n                s += dp[i]\n            if i - maxPts >= 0 and i - maxPts < k:\n                s -= dp[i - maxPts]\n        return sum(dp[k:])","hash":"89fe5c9ebf5ba5386e5c91e6a84c8b8c94c3d4c90b4710dcd87b5d31d2de2257","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/25-MAY 837 New 21 Game.py"}]}],"sources":["solutions"]},"topic-25oct779kthsymbolingrammar":{"key":"topic-25oct779kthsymbolingrammar","number":null,"title":"25 OCT 779 K th Symbol in Grammar","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-OCT 779 K-th Symbol in Grammar.py","code":"class Solution:\n    def kthGrammar(self, N: int, K: int) -> int:\n        return bin(K - 1).count('1') % 2","hash":"7bcd5aa8a31ac89623404ae0158fb52b57e3d3f1f268edadc51780d4c48c9e53","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/25-OCT 779 K-th Symbol in Grammar.py"}]}],"sources":["solutions"]},"topic-25sep389findthedifference":{"key":"topic-25sep389findthedifference","number":null,"title":"25 SEP 389 Find the Difference","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"25-SEP 389 Find the Difference.py","code":"class Solution:\n    def findTheDifference(self, s: str, t: str) -> str:\n        result = 0\n        for char in s:\n            result ^= ord(char)\n        for char in t:\n            result ^= ord(char)\n        return chr(result)","hash":"19eda11478a05a744f24217dee2eecff87b7147f8337163f511911e6984b372a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/25-SEP 389 Find the Difference.py"}]}],"sources":["solutions"]},"topic-26aug646maximumlengthofpairchain":{"key":"topic-26aug646maximumlengthofpairchain","number":null,"title":"26 AUG 646 Maximum Length of Pair Chain","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-AUG 646 Maximum Length of Pair Chain.py","code":"class Solution:\n    def findLongestChain(self, pairs: List[List[int]]) -> int:\n        pairs.sort(key = lambda x : (x[1], x[0]))\n        result, currentPairEnd = 1, pairs[0][1]\n        for pair in pairs[1:]:\n            if currentPairEnd < pair[0]:\n                result, currentPairEnd = result + 1, pair[1]\n        return result","hash":"a466d491b53b0c76de69e2ceb178fe2cd68739d9f1e1bdb0b500fa2e2c25f9d5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/26-AUG 646 Maximum Length of Pair Chain.py"}]}],"sources":["solutions"]},"topic-26jul1870minimumspeedtoarriveontime":{"key":"topic-26jul1870minimumspeedtoarriveontime","number":null,"title":"26 JUL 1870 Minimum Speed to Arrive on Time","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-JUL 1870 Minimum Speed to Arrive on Time.py","code":"class Solution:\n    def minSpeedOnTime(self, dist: List[int], hour: float) -> int:\n        def timeRequired(speed):\n            time = 0.0\n            for index, d in enumerate(dist):\n                t = d / speed\n                time += t if (index == (len(dist) - 1)) else math.ceil(t)\n            return time\n        \n        left, right, minSpeed = 1, 10000000, -1\n        while left <= right:\n            mid = (left + right) >> 1\n            if timeRequired(mid) <= hour:\n                # Move to the left half.\n                minSpeed = mid\n                right = mid - 1\n            else:\n                # Move to the right half.\n                left = mid + 1\n        return minSpeed","hash":"5b4256b257a76f050a3c03368806d905c8954b47180e8d0eee8d0a8509bb2889","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/26-JUL 1870 Minimum Speed to Arrive on Time.py"}]}],"sources":["solutions"]},"topic-26jun2462totalcosttohirekworkers":{"key":"topic-26jun2462totalcosttohirekworkers","number":null,"title":"26 JUN 2462 Total Cost to Hire K Workers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-JUN 2462 Total Cost to Hire K Workers.py","code":"class Solution:\n    def totalCost(self, costs: List[int], k: int, candidates: int) -> int:\n        # Add the first k workers with section id of 0 and \n        # the last k workers with section id of 1 (without duplication) to pq.\n        pq = []\n        for i in range(candidates):\n            pq.append((costs[i], 0))\n        for i in range(max(candidates, len(costs) - candidates), len(costs)):\n            pq.append((costs[i], 1))\n        heapify(pq)\n        result, nextHead, nextTail = 0, candidates, len(costs) - 1 - candidates\n        # Only refill pq if there are workers outside.\n        for _ in range(k):\n            curCost, curSectionId = heappop(pq)\n            result += curCost\n            if nextHead <= nextTail:\n                if curSectionId == 0:\n                    heappush(pq, (costs[nextHead], 0))\n                    nextHead += 1\n                else:\n                    heappush(pq, (costs[nextTail], 1))\n                    nextTail -= 1\n        return result","hash":"edcb2806abb5206126b9c549aaeb4e917da4b54c07f60d1843e0efe5760c7e36","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/26-JUN 2462 Total Cost to Hire K Workers.py"}]}],"sources":["solutions"]},"topic-26may1140stonegameii":{"key":"topic-26may1140stonegameii","number":null,"title":"26 MAY 1140 Stone Game II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-MAY 1140 Stone Game II.py","code":"class Solution:\n    def stoneGameII(self, piles: List[int]) -> int:\n        n = len(piles)\n\n        @lru_cache(None)\n        def helper(p: int, i: int, m: int) -> int:\n            if i == n:\n                return 0\n            result, s = 10**6 if p == 1 else -1, 0\n            for x in range(1, min(2 * m, n - i) + 1):\n                s += piles[i + x - 1]\n                if p == 0:\n                    result = max(result, s + helper(1, i + x, max(x, m)))\n                else:\n                    result = min(result, helper(0, i + x, max(x, m)))\n            return result\n        return helper(0, 0, 1)","hash":"b2db57c10bc5c6f4369d013658e1b7959fb7ee31f3c6cec6013c2ab31ed9c27f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/26-MAY 1140 Stone Game II.py"}]}],"sources":["solutions"]},"topic-26oct823binarytreeswithfactors":{"key":"topic-26oct823binarytreeswithfactors","number":null,"title":"26 OCT 823 Binary Trees With Factors","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-OCT 823 Binary Trees With Factors.py","code":"class Solution:\n    def numFactoredBinaryTrees(self, arr: List[int]) -> int:\n        MOD, N = 10**9 + 7, len(arr)\n        arr.sort()\n        dp, index = [1] * N, {x: i for i, x in enumerate(arr)}\n        for i, x in enumerate(arr):\n            for j in range(i):\n                if x % arr[j] == 0:\n                    right = x // arr[j]\n                    if right in index:\n                        dp[i] += dp[j] * dp[index[right]]\n                        dp[i] %= MOD\n        return sum(dp) % MOD","hash":"6cf466d5ed1c66cc6270f707413686fa53ea2dd314fab5cb003570b818426b54","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/26-OCT 823 Binary Trees With Factors.py"}]}],"sources":["solutions"]},"topic-26sep316removeduplicateletters":{"key":"topic-26sep316removeduplicateletters","number":null,"title":"26 SEP 316 Remove Duplicate Letters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"26-SEP 316 Remove Duplicate Letters.py","code":"class Solution:\n    def removeDuplicateLetters(self, s: str) -> str:\n        stack, seen, lastOccurence = deque([]), set(), {char: index for index, char in enumerate(s)}\n        for index, char in enumerate(s):\n            if char not in seen:\n                while stack and char < stack[-1] and index < lastOccurence[stack[-1]]:\n                    seen.discard(stack.pop())\n                seen.add(char)\n                stack.append(char)\n        return ''.join(stack)","hash":"daf2e13e228f1d3fce6fedc1c78f28f888ae05b3ac0a45e6a2dda119cac4dbe4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/26-SEP 316 Remove Duplicate Letters.py"}]}],"sources":["solutions"]},"topic-27aug403frogjump":{"key":"topic-27aug403frogjump","number":null,"title":"27 AUG 403 Frog Jump","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-AUG 403 Frog Jump.py","code":"class Solution:\n    def canCross(self, stones: List[int]) -> bool:\n        stones_set = set(stones)\n\n        @lru_cache(None)\n        def solve(stone, k):\n            if stone in stones_set:\n                # Current stone is equal to last stone\n                if stone == stones[-1]:\n                    return True\n                # Have max(k-1, 1) to avoid infinite loops\n                for next_leap in range(max(k-1, 1), k+2):\n                    if solve(stone+next_leap, next_leap):\n                        return True\n            return False\n\n        return solve(0, 0)","hash":"564c32f4b2e97901de1a270a4b8d54205d77b8fdf8986a97f7f25cc72f2e9dfe","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/27-AUG 403 Frog Jump.py"}]}],"sources":["solutions"]},"topic-27jul2141maximumrunningtimeofncomputers":{"key":"topic-27jul2141maximumrunningtimeofncomputers","number":null,"title":"27 JUL 2141 Maximum Running Time of N Computers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-JUL 2141 Maximum Running Time of N Computers.py","code":"class Solution:\n    def maxRunTime(self, n: int, batteries: List[int]) -> int:\n        # Get the sum of all extra batteries.\n        batteries.sort()   \n        extra = sum(batteries[:-n])\n        \n        # live stands for the n largest batteries we chose for n computers.\n        live = batteries[-n:]\n        \n        # We increase the total running time using 'extra' by increasing \n        # the running time of the computer with the smallest battery.\n        for i in range(n - 1):\n            # If the target running time is between live[i] and live[i + 1].\n            if extra // (i + 1) < live[i + 1] - live[i]:\n                return live[i] + extra // (i + 1)\n            # Reduce 'extra' by the total power used.\n            extra -= (i + 1) * (live[i + 1] - live[i])\n        \n        # If there is power left, we can increase the running time \n        # of all computers.\n        return live[-1] + extra // n","hash":"2e79269df3584a459369d38977c833f5e83cfb532bda22b7e754738474496842","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/27-JUL 2141 Maximum Running Time of N Computers.py"}]}],"sources":["solutions"]},"topic-27jun373findkpairswithsmallestsums":{"key":"topic-27jun373findkpairswithsmallestsums","number":null,"title":"27 JUN 373 Find K Pairs with Smallest Sums","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-JUN 373 Find K Pairs with Smallest Sums.py","code":"from heapq import heappush, heappop\nclass Solution:\n    def kSmallestPairs(self, nums1: List[int], nums2: List[int], k: int) -> List[List[int]]:\n        m, n, result, visited, count = len(nums1), len(nums2), [], set(), 0\n        minHeap = [(nums1[0] + nums2[0], (0, 0))]\n        visited.add((0, 0))\n        while k > 0 and minHeap:\n            val, (i, j) = heappop(minHeap)\n            result.append([nums1[i], nums2[j]])\n            if i + 1 < m and (i + 1, j) not in visited:\n                heappush(minHeap, (nums1[i + 1] + nums2[j], (i + 1, j)))\n                visited.add((i + 1, j))\n            if j + 1 < n and (i, j + 1) not in visited:\n                heappush(minHeap, (nums1[i] + nums2[j + 1], (i, j + 1)))\n                visited.add((i, j + 1))\n            k = k - 1\n        return result","hash":"7d21f25e32065f21f3be6cb26e11c105cd62f95b84b47c64d3fbdca8a1f600dc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/27-JUN 373 Find K Pairs with Smallest Sums.py"}]}],"sources":["solutions"]},"topic-27may1406stonegameiii":{"key":"topic-27may1406stonegameiii","number":null,"title":"27 MAY 1406 Stone Game III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-MAY 1406 Stone Game III.py","code":"class Solution:\n    def stoneGameIII(self, stoneValue: List[int]) -> str:\n        n = len(stoneValue)\n\n        @lru_cache(None)\n        def helper(i: int) -> int:\n            if i == n:\n                return 0\n            result = stoneValue[i] - helper(i + 1)\n            if i + 2 <= n:\n                result = max(result, stoneValue[i] + stoneValue[i + 1] - helper(i + 2))\n            if i + 3 <= n:\n                result = max(result, stoneValue[i] + stoneValue[i + 1] + stoneValue[ i + 2] - helper(i + 3))\n            return result\n        \n        result = helper(0)\n        if result > 0:\n            return 'Alice'\n        elif result < 0:\n            return 'Bob'\n        else:\n            return 'Tie'","hash":"b1de7f2286798172e3abd1c04039f55e6e52e7e22ca9f30635ab8f7ce546eb35","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/27-MAY 1406 Stone Game III.py"}]}],"sources":["solutions"]},"topic-27oct5longestpalindromicsubstring":{"key":"topic-27oct5longestpalindromicsubstring","number":null,"title":"27 OCT 5 Longest Palindromic Substring","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-OCT 5 Longest Palindromic Substring.py","code":"class Solution:\n    def longestPalindrome(self, s: str) -> str:\n        n, start, end = len(s), 0, 0\n        if n in [0, 1]:\n            return s\n        def palindromeLength(l, r):\n            while l >= 0 and r < n and s[l] == s[r]:\n                l, r = l - 1, r + 1\n            return r - l - 1\n        for i in range(n):\n            maxPalindromeLength = max(palindromeLength(i, i), palindromeLength(i, i + 1))\n            if maxPalindromeLength > end - start:\n                end, start = i + (maxPalindromeLength // 2), i - ((maxPalindromeLength - 1) // 2)\n        return s[start : end + 1]","hash":"332e25dcd6379c2b090b334006cc704b64781e8853a9d9fb89e9dd8144c24714","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/27-OCT 5 Longest Palindromic Substring.py"}]}],"sources":["solutions"]},"topic-27sep880decodedstringatindex":{"key":"topic-27sep880decodedstringatindex","number":null,"title":"27 SEP 880 Decoded String at Index","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"27-SEP 880 Decoded String at Index.py","code":"class Solution(object):\n    def decodeAtIndex(self, S, K):\n        size = 0\n        # Find size = length of decoded string\n        for c in S:\n            if c.isdigit():\n                size *= int(c)\n            else:\n                size += 1\n\n        for c in reversed(S):\n            K %= size\n            if K == 0 and c.isalpha():\n                return c\n\n            if c.isdigit():\n                size /= int(c)\n            else:\n                size -= 1","hash":"aba799df6b7ca891bdcfb1b970201826505c27eb242caf04f522afd88973aebf","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/27-SEP 880 Decoded String at Index.py"}]}],"sources":["solutions"]},"topic-28aug225implementstackusingqueues":{"key":"topic-28aug225implementstackusingqueues","number":null,"title":"28 AUG 225 Implement Stack using Queues","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-AUG 225 Implement Stack using Queues.py","code":"class MyStack:\n\n    def __init__(self):\n        self.queue = deque([])\n\n    def push(self, x: int) -> None:\n        self.queue.append(x)\n        size = len(self.queue)\n        while size > 1:\n            self.queue.append(self.queue.popleft())\n            size -= 1\n\n    def pop(self) -> int:\n        return self.queue.popleft()\n\n    def top(self) -> int:\n        return self.queue[0]\n\n    def empty(self) -> bool:\n        return len(self.queue) == 0\n\n\n# Your MyStack object will be instantiated and called as such:\n# obj = MyStack()\n# obj.push(x)\n# param_2 = obj.pop()\n# param_3 = obj.top()\n# param_4 = obj.empty()","hash":"d36f6b8524cadae21f98d396fdedb422770395f3a265678c1451468b8ed6dbcc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/28-AUG 225 Implement Stack using Queues.py"}]}],"sources":["solutions"]},"topic-28jul486predictthewinner":{"key":"topic-28jul486predictthewinner","number":null,"title":"28 JUL 486 Predict the Winner","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-JUL 486 Predict the Winner.py","code":"class Solution:\n    def PredictTheWinner(self, nums: List[int]) -> bool:\n        @lru_cache(None)\n        def maximumDifference(leftIndex: int, rightIndex: int) -> int:\n            if leftIndex == rightIndex:\n                return nums[leftIndex]\n            scoreByLeft = nums[leftIndex] - maximumDifference(leftIndex + 1, rightIndex)\n            scoreByRight = nums[rightIndex] - maximumDifference(leftIndex, rightIndex - 1)\n            return max(scoreByLeft, scoreByRight)\n        return maximumDifference(0, len(nums) - 1) >= 0","hash":"30f0b2123b5f8859c8c410b238461ea559e682608967d55adef0727934b63fad","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/28-JUL 486 Predict the Winner.py"}]}],"sources":["solutions"]},"topic-28jun1514pathwithmaximumprobability":{"key":"topic-28jun1514pathwithmaximumprobability","number":null,"title":"28 JUN 1514 Path with Maximum Probability","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-JUN 1514 Path with Maximum Probability.py","code":"class Solution:\n    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:\n        graph = defaultdict(list)\n        for i, (u, v) in enumerate(edges):\n            graph[u].append((v, succProb[i]))\n            graph[v].append((u, succProb[i]))\n        maxProb = [0.0] * n\n        maxProb[start] = 1.0\n        pq = [(-1.0, start)]\n        while pq:\n            curProb, curNode = heapq.heappop(pq)\n            if curNode == end:\n                return -curProb\n            for nextNode, pathProb in graph[curNode]:\n                if -curProb * pathProb > maxProb[nextNode]:\n                    maxProb[nextNode] = -curProb * pathProb\n                    heapq.heappush(pq, (-maxProb[nextNode], nextNode))\n        return 0.0","hash":"bf4968f0905beb566b8f1f6414d5c1426215f1628748cc6640fb530854fea1c2","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/28-JUN 1514 Path with Maximum Probability.py"}]}],"sources":["solutions"]},"topic-28may1547minimumcosttocutastick":{"key":"topic-28may1547minimumcosttocutastick","number":null,"title":"28 MAY 1547 Minimum Cost to Cut a Stick","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-MAY 1547 Minimum Cost to Cut a Stick.py","code":"class Solution:\n    def minCost(self, n: int, cuts: List[int]) -> int:\n        cuts = [0] + sorted(cuts) + [n]\n\n        @lru_cache(None)\n        def cost(left: int, right: int) -> int:\n            if right - left == 1:\n                return 0\n            return min(cost(left, mid) + cost(mid, right) + cuts[right] - cuts[left] for mid in range(left + 1, right))\n        \n        return cost(0, len(cuts) - 1)","hash":"85bf7945f96c330b804eb03f404a159e508f0f58bd198ba518aa6344e33ea0b5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/28-MAY 1547 Minimum Cost to Cut a Stick.py"}]}],"sources":["solutions"]},"topic-28oct1220countvowelspermutation":{"key":"topic-28oct1220countvowelspermutation","number":null,"title":"28 OCT 1220 Count Vowels Permutation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-OCT 1220 Count Vowels Permutation.py","code":"# a => e + i + u\n# e => a + i\n# i => e + o\n# o => i\n# u => i + o\n\nclass Solution:\n    def countVowelPermutation(self, n: int) -> int:\n        MOD, curr = 1000000007, [1] * 5\n        for i in range(2, n + 1):\n            curr[0], curr[1], curr[2], curr[3], curr[4] = (curr[1] + curr[2] + curr[4]) % MOD, (curr[0] + curr[2]) % MOD, (curr[1] + curr[3]) % MOD, (curr[2]) % MOD, (curr[2] + curr[3]) % MOD\n        return sum(curr) % MOD","hash":"b7078b7c9c92c785883b215625a6a3e3a37117b25a40fba1dd55e7ccbb2dce1b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/28-OCT 1220 Count Vowels Permutation.py"}]}],"sources":["solutions"]},"topic-28sep905sortarraybyparity":{"key":"topic-28sep905sortarraybyparity","number":null,"title":"28 SEP 905 Sort Array By Parity","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"28-SEP 905 Sort Array By Parity.py","code":"class Solution:\n    def sortArrayByParity(self, A: List[int]) -> List[int]:\n        i, j = 0, len(A) - 1\n        while i < j:\n            if A[i] % 2 > A[j] % 2:\n                A[i], A[j] = A[j], A[i]\n            if A[i] % 2 == 0:\n                i += 1\n            if A[j] % 2 == 1:\n                j -= 1\n        return A","hash":"c1d9c8f7efe2616ddcfd5f51aee686d00f50eb40d10d81b665f8ad25c8c81a1d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/28-SEP 905 Sort Array By Parity.py"}]}],"sources":["solutions"]},"topic-29aug2483minimumpenaltyforashop":{"key":"topic-29aug2483minimumpenaltyforashop","number":null,"title":"29 AUG 2483 Minimum Penalty for a Shop","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-AUG 2483 Minimum Penalty for a Shop.py","code":"class Solution:\n    def bestClosingTime(self, customers: str) -> int:\n        # Start with closing at hour 0 and assume the current penalty is 0.\n        cur_penalty = min_penalty = 0\n        earliest_hour = 0\n        \n        for i, ch in enumerate(customers):\n            # If status in hour i is 'Y', moving it to open hours decrement\n            # penalty by 1. Otherwise, moving 'N' to open hours increment\n            # penatly by 1.\n            if ch == 'Y':\n                cur_penalty -= 1\n            else:\n                cur_penalty += 1\n\n            # Update earliest_hour if a smaller penatly is encountered\n            if cur_penalty < min_penalty:\n                earliest_hour = i + 1\n                min_penalty = cur_penalty\n                \n        return earliest_hour","hash":"41517a4ac28bf537aca32c1d34f5387690c7f3e73e3050ca07020178bfe7d6a5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/29-AUG 2483 Minimum Penalty for a Shop.py"}]}],"sources":["solutions"]},"topic-29jul808soupservings":{"key":"topic-29jul808soupservings","number":null,"title":"29 JUL 808 Soup Servings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-JUL 808 Soup Servings.py","code":"class Solution:\n    def soupServings(self, n: int) -> float:\n        m = math.ceil(n / 25)\n        @lru_cache(None)\n        def helper(i: int, j: int) -> float:\n            if i <= 0 and j <= 0:\n                return 0.5\n            if i <= 0:\n                return 1.0\n            if j <= 0:\n                return 0.0\n            return (helper(i - 4, j) + helper(i - 3, j - 1) + helper(i - 2, j - 2) + helper(i - 1, j - 3)) / 4.0\n        for k in range(1, m + 1):\n            if helper(k, k) > 1 - 1e-5:\n                return 1.0\n        return helper(m, m)","hash":"03709586425fb9443da994dd3f4989b77d8d49af143d632f59bcd802ef172dbd","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/29-JUL 808 Soup Servings.py"}]}],"sources":["solutions"]},"topic-29jun864shortestpathtogetallkeys":{"key":"topic-29jun864shortestpathtogetallkeys","number":null,"title":"29 JUN 864 Shortest Path to Get All Keys","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-JUN 864 Shortest Path to Get All Keys.py","code":"class Solution:\n    def shortestPathAllKeys(self, grid: List[str]) -> int:\n        m, n = len(grid), len(grid[0])\n        queue = collections.deque()\n        \n        # seen['key'] is only for BFS with key state equals 'keys'\n        seen = collections.defaultdict(set)\n        \n        key_set, lock_set = set(), set()\n        all_keys = 0\n        start_r, start_c = -1, -1\n        for i in range(m):\n            for j in range(n):\n                cell = grid[i][j]\n                if cell in 'abcdef':\n                    all_keys += (1 << (ord(cell) - ord('a')))\n                    key_set.add(cell)\n                if cell in 'ABCDEF':\n                    lock_set.add(cell)\n                if cell == \"@\":\n                    start_r, start_c = i, j\n        \n        # [row, column, key_state, distance]\n        queue.append((start_r, start_c, 0, 0))\n        seen[0].add((start_r, start_c))\n        \n        while queue:\n            cur_r, cur_c, keys, dist = queue.popleft()\n            for dr, dc in ((0, 1), (1, 0), (-1, 0), (0, -1)):\n                new_r, new_c = cur_r + dr, cur_c + dc\n                \n                # If this cell (new_r, new_c) is reachable.\n                if 0 <= new_r < m and 0 <= new_c < n and grid[new_r][new_c] != '#':\n                    cell = grid[new_r][new_c]\n                    \n                    # If it is a key we haven't picked up yet\n                    if cell in key_set and not ((1 << (ord(cell) - ord('a'))) & keys):\n                        new_keys = (keys | (1 << (ord(cell) - ord('a'))))\n\n                        # If we collect all keys, return dist + 1. \n                        # Otherwise, just add this state to seen and queue.\n                        if new_keys == all_keys:\n                            return dist + 1\n                        seen[new_keys].add((new_r, new_c))\n                        queue.append((new_r, new_c, new_keys, dist + 1))\n                      \n                    # If it is a lock and we don't have its key, continue.\n                    elif cell in lock_set and not (keys & (1 << (ord(cell) - ord('A')))):\n                        continue\n                        \n                    # We can walk to this cell if we haven't been here before with the same key state.\n                    elif (new_r, new_c) not in seen[keys]:\n                        seen[keys].add((new_r, new_c))\n                        queue.append((new_r, new_c, keys, dist + 1))\n            \n        return -1","hash":"64a10edc3ab7f8c88ef9e680a3be08929aeaa83f8de14687abac005e77c758e3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/29-JUN 864 Shortest Path to Get All Keys.py"}]}],"sources":["solutions"]},"topic-29may1603designparkingsystem":{"key":"topic-29may1603designparkingsystem","number":null,"title":"29 MAY 1603 Design Parking System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-MAY 1603 Design Parking System.py","code":"class ParkingSystem:\n\n    def __init__(self, big: int, medium: int, small: int):\n        self.bigSize, self.bigCount, self.mediumSize, self.mediumCount, self.smallSize, self.smallCount = big, 0, medium, 0, small, 0\n\n    def addCar(self, carType: int) -> bool:\n        if carType == 1:\n            if self.bigCount < self.bigSize:\n                self.bigCount += 1\n                return True\n            return False\n        elif carType == 2:\n            if self.mediumCount < self.mediumSize:\n                self.mediumCount += 1\n                return True\n            return False\n        elif carType == 3:\n            if self.smallCount < self.smallSize:\n                self.smallCount += 1\n                return True\n            return False\n        return False\n\n\n# Your ParkingSystem object will be instantiated and called as such:\n# obj = ParkingSystem(big, medium, small)\n# param_1 = obj.addCar(carType)","hash":"6387f3af9774d006ea659a63c8879dbc66ed20a5c618e86c8fe958031b9b2ec5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/29-MAY 1603 Design Parking System.py"}]}],"sources":["solutions"]},"topic-29oct458poorpigs":{"key":"topic-29oct458poorpigs","number":null,"title":"29 OCT 458 Poor Pigs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-OCT 458 Poor Pigs.py","code":"class Solution:\n    def poorPigs(self, buckets: int, minutesToDie: int, minutesToTest: int) -> int:\n        # 4, 1 => log(4)\n        # 4, 2 => log(4/2)\n\n        # When there is only 1 chance to test, we need at least log_2(buckets) pigs to test\n        # When there is n chance to test, the optimum strategy requires finding the pig at \n        # the last test. For example, buckets = 5, n_tests = 2, if we have two pigs, we can\n        # do 1,2 for pig 1, 3,4 for pig 2. If both die, it's 5, if one of them die, we can\n        # use the other pig to test. If Buckets = 6, naively, we can do 1,2,3 for pig 1, and \n        # 3,4,5 for # pig 2. If one dies, we still have 3 to choose which requires another pig,\n        # increasing the pigs needed to 3. If we do 1,2,3 for pig 1 and 3,4,5 for pig 2, if\n        # neither die, it's 6; if both die, it's 3; if one die, we can test with the other one.\n        # this means that pigs required is still 2. For buckets = 7, we can do 1,2,3,4 for \n        # pig 1, 4,5,6 for pig 2.\n        #\n        # At each test, we can choose how many buckets to elmintate and how many pigs alive\n        # for the next test. We can do dfs to find the methods to use the least pig. If we\n        # have n buckets, we know that the upper bound is log2(n). We know that the lower\n        # bound is 1. We can try all numbers of pigs and find the pigs alive after 1 round.\n        # The minimum number of pigs surviving is the overlap of the buckets for each pig.\n        # Each time we want to mix buckets so that each combination of the liveness of the pigs\n        # corresponds to 1 section of buckets containing posion. If all buckets goes out\n        # 1*6 => 1,2,3 | 2,3,4 | 3,4,5\n        # \n        # buckets = 4, test = 2: ln_2(buckets / 2)\n        # buckets = 5, test = 2\n\n        # Instead of counting how many pigs are alive for each test case and figuring out if the\n        # pigs are enough, we can try to figure out how many combinations of states does the sum\n        # of i = 1, 2.., n pigs could represent.\n        # \n\n        # if buckets <= 2:\n        #     return 1\n\n        n_tests = minutesToTest // minutesToDie\n        print(math.log(buckets) / math.log(n_tests + 1))\n        return math.ceil(round(math.log(buckets) / math.log(n_tests + 1), 10))","hash":"42a792db4f1dd9dc22c5a0c13f30cad846b98542cbe52e9b9ff6e7a3677b861c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/29-OCT 458 Poor Pigs.py"}]}],"sources":["solutions"]},"topic-29sep896monotonicarray":{"key":"topic-29sep896monotonicarray","number":null,"title":"29 SEP 896 Monotonic Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"29-SEP 896 Monotonic Array.py","code":"class Solution:\n    def isMonotonic(self, nums: List[int]) -> bool:\n        diff, same = 0, 0\n        for i in range(len(nums) - 1):\n            if nums[i] < nums[i + 1]:\n                diff += 1\n            elif nums[i] > nums[i + 1]:\n                diff -= 1\n            else:\n                same += 1\n        return (len(nums) - 1 - same) == abs(diff)","hash":"877ede7bab869dc93735898b354116fb8f203704ea1e8e6b6380aaaa439e429c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/29-SEP 896 Monotonic Array.py"}]}],"sources":["solutions"]},"topic-30aug2366minimumreplacementstosortthearray":{"key":"topic-30aug2366minimumreplacementstosortthearray","number":null,"title":"30 AUG 2366 Minimum Replacements to Sort the Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-AUG 2366 Minimum Replacements to Sort the Array.py","code":"class Solution:\n    def minimumReplacement(self, nums: List[int]) -> int:\n        result, n = 0, len(nums)\n        # Start from the second last element, as the last one is always sorted.\n        for i in range(n - 2, -1, -1):\n            # No need to break if they are already in order.\n            if nums[i] <= nums[i + 1]:\n                continue\n            # Count how many elements are made from breaking nums[i].\n            numElements = (nums[i] + nums[i + 1] - 1) // nums[i + 1]\n            # It requires numElements - 1 replacement operations.\n            result += numElements - 1\n            # Maximize nums[i] after replacement.\n            nums[i] = nums[i] // numElements\n        return result","hash":"83c853f5aad9587e04abb64d47fd1c653864f081dbcabc223b16717e6c4a2f1c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/30-AUG 2366 Minimum Replacements to Sort the Array.py"}]}],"sources":["solutions"]},"topic-30jul664strangeprinter":{"key":"topic-30jul664strangeprinter","number":null,"title":"30 JUL 664 Strange Printer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-JUL 664 Strange Printer.py","code":"class Solution:\n    def strangePrinter(self, s: str) -> int:\n        n = len(s)\n        dp = [[-1] * n for _ in range(n)]\n        def solve(left, right):\n            if dp[left][right] != -1:\n                return dp[left][right]\n            dp[left][right] = n\n            j = -1\n            for i in range(left, right):\n                if s[i] != s[right] and j == -1:\n                    j = i\n                if j != -1:\n                    dp[left][right] = min(dp[left][right], 1 + solve(j, i) + solve(i + 1, right))     \n            if j == -1:\n                dp[left][right] = 0\n            return dp[left][right]\n        return solve(0, n - 1) + 1","hash":"eac66e0bcf891b8de530e15fe295f3ec41aa1d5224ccef5b401627446412dae6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/30-JUL 664 Strange Printer.py"}]}],"sources":["solutions"]},"topic-30jun1970lastdaywhereyoucanstillcross":{"key":"topic-30jun1970lastdaywhereyoucanstillcross","number":null,"title":"30 JUN 1970 Last Day Where You Can Still Cross","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-JUN 1970 Last Day Where You Can Still Cross.py","code":"class DSU:\n    def __init__(self, n):\n        self.root = list(range(n))\n        self.size = [1] * n\n\n    def find(self, x):\n        if self.root[x] != x:\n            self.root[x] = self.find(self.root[x])\n        return self.root[x]\n\n    def union(self, x, y):\n        root_x = self.find(x)\n        root_y = self.find(y)\n        if root_x == root_y:\n            return\n        \n        if self.size[root_x] > self.size[root_y]:\n            root_x, root_y = root_y, root_x\n        self.root[root_x] = root_y\n        self.size[root_y] += self.size[root_x]\n\nclass Solution:\n    def latestDayToCross(self, row: int, col: int, cells: List[List[int]]) -> int:\n        dsu = DSU(row * col + 2)\n        grid = [[1] * col for _ in range(row)]\n        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]\n\n        for i in range(len(cells) - 1, -1, -1):\n            r, c = cells[i][0] - 1, cells[i][1] - 1\n            grid[r][c] = 0\n            index_1 = r * col + c + 1\n            for dr, dc in directions:\n                new_r, new_c = r + dr, c + dc\n                index_2 = new_r * col + new_c + 1\n                if 0 <= new_r < row and 0 <= new_c < col and grid[new_r][new_c] == 0:\n                    dsu.union(index_1, index_2)\n                    \n            if r == 0:\n                dsu.union(0, index_1)\n            if r == row - 1:\n                dsu.union(row * col + 1, index_1)\n            if dsu.find(0) == dsu.find(row * col + 1):\n                return i","hash":"923ec1dc062dd78d3b197cc6d6b0ce6e7381bcfc5830fb35f7dbfebcdfa7d8a4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-06 Leetcoding Challenge/30-JUN 1970 Last Day Where You Can Still Cross.py"}]}],"sources":["solutions"]},"topic-30may705designhashset":{"key":"topic-30may705designhashset","number":null,"title":"30 MAY 705 Design Hash Set","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-MAY 705 Design HashSet.py","code":"class MyHashSet:\n\n    def __init__(self):\n        self.hashSet = set()\n\n    def add(self, key: int) -> None:\n        self.hashSet.add(key)\n\n    def remove(self, key: int) -> None:\n        self.hashSet.discard(key)\n\n    def contains(self, key: int) -> bool:\n        \"\"\"\n        Returns true if this set contains the specified element\n        \"\"\"\n        return key in self.hashSet\n\n\n# Your MyHashSet object will be instantiated and called as such:\n# obj = MyHashSet()\n# obj.add(key)\n# obj.remove(key)\n# param_3 = obj.contains(key)","hash":"c383832ad66f366813f50ceefbf7042ebfccee3fb9f0ed45a6048aae9d7da999","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/30-MAY 705 Design HashSet.py"}]}],"sources":["solutions"]},"topic-30oct1356sortintegersbythenumberof1bits":{"key":"topic-30oct1356sortintegersbythenumberof1bits","number":null,"title":"30 OCT 1356 Sort Integers by The Number of 1 Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-OCT 1356 Sort Integers by The Number of 1 Bits.py","code":"class Solution:\n    def sortByBits(self, arr: List[int]) -> List[int]:\n        arr.sort()\n        return sorted(arr, key = lambda x : bin(x)[2:].count('1'))","hash":"a2da369739f42ab043cbd5eb4fe0165a1bb6f9d0bac08ec2a71cb069743ea6b4","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/30-OCT 1356 Sort Integers by The Number of 1 Bits.py"}]}],"sources":["solutions"]},"topic-30sep456132pattern":{"key":"topic-30sep456132pattern","number":null,"title":"30 SEP 456 132 Pattern","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"30-SEP 456 132 Pattern.py","code":"class Solution:\n    def find132pattern(self, nums: List[int]) -> bool:\n        numberOfItems = len(nums)\n        if numberOfItems < 3:\n            return False\n        stack, minArray = [], [0] * numberOfItems\n        minArray[0] = nums[0]\n        for i in range(1, numberOfItems):\n            minArray[i] = min(minArray[i - 1], nums[i])\n        for i in range(numberOfItems - 1, -1, -1):\n            if nums[i] > minArray[i]:\n                while stack and stack[-1] <= minArray[i]:\n                    stack.pop()\n                if stack and stack[-1] < nums[i]:\n                    return True\n                stack.append(nums[i])\n        return False","hash":"ea873e7adadfedadc563a1e3cd81065163fe65fb388c41eba48366e1807d5cdf","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-09 Leetcoding Challenge/30-SEP 456 132 Pattern.py"}]}],"sources":["solutions"]},"topic-31aug1326minimumnumberoftapstoopentowateragarden":{"key":"topic-31aug1326minimumnumberoftapstoopentowateragarden","number":null,"title":"31 AUG 1326 Minimum Number of Taps to Open to Water a Garden","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"31-AUG 1326 Minimum Number of Taps to Open to Water a Garden.py","code":"class Solution:\n    def minTaps(self, n: int, ranges: List[int]) -> int:\n        # Create a list to track the maximum reach for each position\n        maximumReach = [0] * (n + 1)\n\n        # Calculate the maximum reach for each tap\n        for i in range(len(ranges)):\n            # Calculate the leftmost position the tap can reach\n            start = max(0, i - ranges[i])\n            # Calculate the rightmost position the tap can reach\n            end = min(n, i + ranges[i])\n            # Update the maximum reach for the leftmost position\n            maximumReach[start] = max(maximumReach[start], end)\n\n        # Number of taps used\n        taps = 0\n        # Current rightmost position reached\n        currentEnd = 0\n        # Next rightmost position that can be reached\n        nextEnd = 0\n\n        # Iterate through the garden\n        for i in range(n + 1):\n            if i > nextEnd:\n                # Current position cannot be reached\n                return -1\n\n            if i > currentEnd:\n                # Increment taps when moving to a new tap\n                taps += 1\n                # Move to the rightmost position that can be reached\n                currentEnd = nextEnd\n\n            # Update the next rightmost position that can be reached\n            nextEnd = max(nextEnd, maximumReach[i])\n\n        # Return the minimum number of taps used\n        return taps","hash":"83113f590dd99cbee97f46d81880cb09aea57df068313683f847f6588de5dbe5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-08 Leetcoding Challenge/31-AUG 1326 Minimum Number of Taps to Open to Water a Garden.py"}]}],"sources":["solutions"]},"topic-31jul712minimumasciideletesumfortwostrings":{"key":"topic-31jul712minimumasciideletesumfortwostrings","number":null,"title":"31 JUL 712 Minimum ASCII Delete Sum for Two Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"31-JUL 712 Minimum ASCII Delete Sum for Two Strings.py","code":"class Solution:\n    def minimumDeleteSum(self, s1: str, s2: str) -> int:\n    \n        # Dictionary to store the result of each sub-problem\n        saved_result = {}\n\n        # Return minimum cost to make s1[0...i] and s2[0...j] equal\n        def compute_cost(i, j):\n\n            # If both strings are empty, then no deletion is required\n            if i < 0 and j < 0:\n                return 0\n            \n            # If already computed, then return the result from the dictionary\n            if (i, j) in saved_result:\n                return saved_result[(i, j)]\n            \n            # If any one string is empty, delete all characters of the other string\n            if i < 0:\n                saved_result[(i, j)] = ord(s2[j]) + compute_cost(i, j-1)\n                return saved_result[(i, j)]\n            if j < 0:\n                saved_result[(i, j)] = ord(s1[i]) + compute_cost(i-1, j)\n                return saved_result[(i, j)]\n            \n            # Call sub-problem depending on s1[i] and s2[j]\n            # Save the computed result.\n            if s1[i] == s2[j]:\n                saved_result[(i, j)] = compute_cost(i-1, j-1)\n            else:\n                saved_result[(i, j)] = min(\n                    ord(s1[i]) + compute_cost(i-1, j),\n                    ord(s2[j]) + compute_cost(i, j-1)\n                )\n\n            return saved_result[(i, j)]\n\n        # Return the result of the main problem\n        return compute_cost(len(s1)-1, len(s2)-1)","hash":"1666fe3e8b9e238126094b666caf0287aa3c025a64163c2bc73c82e7e4617916","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-07 Leetcoding Challenge/31-JUL 712 Minimum ASCII Delete Sum for Two Strings.py"}]}],"sources":["solutions"]},"topic-31may1396designundergroundsystem":{"key":"topic-31may1396designundergroundsystem","number":null,"title":"31 MAY 1396 Design Underground System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"31-MAY 1396 Design Underground System.py","code":"class UndergroundSystem:\n\n    def __init__(self):\n        self.checkInData, self.journeyData = {}, defaultdict(lambda : [0, 0])\n\n    def checkIn(self, id: int, stationName: str, t: int) -> None:\n        self.checkInData[id] = (stationName, t)\n\n    def checkOut(self, id: int, stationName: str, t: int) -> None:\n        startStation, startTime = self.checkInData.pop(id)\n        self.journeyData[(startStation, stationName)][0] += (t - startTime)\n        self.journeyData[(startStation, stationName)][1] += 1\n\n    def getAverageTime(self, startStation: str, endStation: str) -> float:\n        totalTime, totalTrips = self.journeyData[(startStation, endStation)]\n        return totalTime / totalTrips\n\n\n# Your UndergroundSystem object will be instantiated and called as such:\n# obj = UndergroundSystem()\n# obj.checkIn(id,stationName,t)\n# obj.checkOut(id,stationName,t)\n# param_3 = obj.getAverageTime(startStation,endStation)","hash":"a1bcf1857ceeb35de8e4177b24f69a1aa0f6f0a0b29abaf636e879f1f502c16e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-05 Leetcoding Challenge/31-MAY 1396 Design Underground System.py"}]}],"sources":["solutions"]},"topic-31oct2433findtheoriginalarrayofprefixxor":{"key":"topic-31oct2433findtheoriginalarrayofprefixxor","number":null,"title":"31 OCT 2433 Find The Original Array of Prefix Xor","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"31-OCT 2433 Find The Original Array of Prefix Xor.py","code":"class Solution:\n    def findArray(self, pref: List[int]) -> List[int]:\n        result = [0] * len(pref)\n        result[0] = pref[0]\n        for i in range(1, len(pref)):\n            result[i] = pref[i - 1] ^ pref[i]\n        return result","hash":"1a1374083cb981fc90e291cb370e979ba7eea8d60825aae451fa551d3a19e9f9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-10 Leetcoding Challenge/31-OCT 2433 Find The Original Array of Prefix Xor.py"}]}],"sources":["solutions"]},"topic-3sumhashsetapproach":{"key":"topic-3sumhashsetapproach","number":null,"title":"3Sum Hashset Approach","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"3Sum - Hashset Approach.py","code":"class Solution:\n    def threeSum(self, nums: List[int]) -> List[List[int]]:\n        result = []\n        \n        def twoSums(nums, i):\n            nonlocal result\n            seenSet = set()\n            j = i + 1\n            while j < len(nums):\n                complement = -nums[i] - nums[j]\n                if complement in seenSet:\n                    result.append([nums[i], complement, nums[j]])\n                    while j + 1 < len(nums) and nums[j] == nums[j + 1]:\n                        j += 1\n                seenSet.add(nums[j])\n                j += 1\n                \n        nums.sort()\n        for i, num in enumerate(nums):\n            if num > 0:\n                break\n            if i == 0 or nums[i - 1] != num:\n                twoSums(nums, i)\n        return result","hash":"c469c1670c1cac2e3776d11625035fbdfb8964cc44398f717db5960dbdebe345","origins":[{"source":"solutions","path":"Google Interview Questions/3Sum - Hashset Approach.py"}]}],"sources":["solutions"]},"topic-3sumtwopointersapproach":{"key":"topic-3sumtwopointersapproach","number":null,"title":"3Sum Two Pointers Approach","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"3Sum - Two Pointers Approach.py","code":"class Solution:\n    def threeSum(self, nums: List[int]) -> List[List[int]]:\n        result = []\n        \n        def twoSums(nums, i):\n            nonlocal result\n            low = i + 1\n            high = len(nums) - 1\n            while low < high:\n                currentSum = nums[i] + nums[low] + nums[high]\n                if currentSum > 0:\n                    high -= 1\n                elif currentSum < 0:\n                    low += 1\n                else:\n                    result.append([nums[i], nums[low], nums[high]])\n                    low += 1\n                    high -= 1\n                    while low < high and nums[low - 1] == nums[low]:\n                        low += 1\n                \n        nums.sort()\n        for i, num in enumerate(nums):\n            if num > 0:\n                break\n            if i == 0 or nums[i - 1] != num:\n                twoSums(nums, i)\n        return result","hash":"3ba3cee5c06b84d11506bd68eae65b44f913ac77c8010a6581980d34ae42ed01","origins":[{"source":"solutions","path":"Google Interview Questions/3Sum - Two Pointers Approach.py"}]}],"sources":["solutions"]},"topic-3sumwithmultiplicity":{"key":"topic-3sumwithmultiplicity","number":null,"title":"3Sum With Multiplicity","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"3Sum With Multiplicity.py","code":"class Solution:\n    def threeSumMulti(self, arr: List[int], target: int) -> int:\n        MOD, result = 10**9 + 7, 0\n        arr.sort()\n        for i, x in enumerate(arr):\n            T, j, k = target - x, i + 1, len(arr) - 1\n            while j < k:\n                if arr[j] + arr[k] < T:\n                    j += 1\n                elif arr[j] + arr[k] > T:\n                    k -= 1\n                elif arr[j] != arr[k]:\n                    left = right = 1\n                    while j + 1 < k and arr[j] == arr[j + 1]:\n                        left, j = left + 1, j + 1\n                    while k - 1 > j and arr[k] == arr[k - 1]:\n                        right, k = right + 1, k - 1\n                    result += left * right\n                    result %= MOD\n                    j, k = j + 1, k - 1\n                else:\n                    result += (k - j + 1) * (k - j) // 2\n                    result %= MOD\n                    break\n        return result","hash":"fc11d644af0a5142017922e56bd72d1389a5b700835e03ba65c2c021d0882878","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/3Sum With Multiplicity.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/3Sum With Multiplicity.py"}]}],"sources":["solutions"]},"topic-4sumii":{"key":"topic-4sumii","number":null,"title":"4Sum II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"4Sum II.py","code":"class Solution:\n    def fourSumCount(self, A: List[int], B: List[int], C: List[int], D: List[int]) -> int:\n        count, hashMap = 0, defaultdict(int)\n        for a in A:\n            for b in B:\n                hashMap[a + b] += 1\n        for c in C:\n            for d in D:\n                count += hashMap[-(c + d)]\n        return count","hash":"11ac929d032d75972097ce196b0fcc07977ad25c41502ccbfea6bfc7bf7473b7","origins":[{"source":"solutions","path":"Hash Table/4Sum II.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/4Sum II.py"}]},{"language":"python","name":"4Sum II.py","code":"class Solution:\n    def fourSumCount(self, nums1: List[int], nums2: List[int], nums3: List[int], nums4: List[int]) -> int:\n        count, hashMap = 0, defaultdict(int)\n        for a in nums1:\n            for b in nums2:\n                hashMap[a + b] += 1\n        for c in nums3:\n            for d in nums4:\n                count += hashMap[-(c + d)]\n        return count","hash":"d4a8fd86a6e7dcc3ebda37a3c9ba51652ac9a8d15f81eabe029feb493c4d029f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/4Sum II.py"}]}],"sources":["solutions"]},"topic-activeusers":{"key":"topic-activeusers","number":null,"title":"Active Users","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Active Users.sql","code":"/* Write your PL/SQL query statement below */\nSELECT accounts.id id, accounts.name FROM Accounts accounts INNER JOIN (SELECT a.id FROM Logins a CROSS JOIN Logins b CROSS JOIN Logins c CROSS JOIN Logins d CROSS JOIN Logins e WHERE a.id = b.id AND b.id = c.id AND c.id = d.id AND d.id = e.id AND to_char(a.login_date + 1) = to_char(b.login_date) AND to_char(b.login_date + 1) = to_char(c.login_date) AND to_char(c.login_date + 1) = to_char(d.login_date) AND to_char(d.login_date + 1) = to_char(e.login_date) GROUP BY a.id) logs ON accounts.id = logs.id ORDER BY id;","hash":"a60fcf062cec9ceded77d55e33e15eb3443dbc0ea1e27fb484b8a0be0e524108","origins":[{"source":"solutions","path":"Active Users.sql"}]}],"sources":["solutions"]},"topic-addandsearchword01":{"key":"topic-addandsearchword01","number":null,"title":"Add and Search Word 01","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add and Search Word - 01.py","code":"class WordDictionary:\n\n    def __init__(self):\n        self.trie = {}\n\n    def addWord(self, word: str) -> None:\n        node = self.trie\n        for c in word:\n            if node.get(c) == None:\n                node[c] = {}\n            node = node[c]\n        node['$'] = True\n\n    def search(self, word: str) -> bool:\n        def searchInNode(word, node) -> bool:\n            for i, c in enumerate(word):\n                if node.get(c) == None:\n                    if c == '.':\n                        for x in node:\n                            if x != '$' and searchInNode(word[i+1:], node.get(x)):\n                                return True\n                    return False\n                else:\n                    node = node[c]\n            return '$' in node\n        return searchInNode(word, self.trie)\n\n# Your WordDictionary object will be instantiated and called as such:\n# obj = WordDictionary()\n# obj.addWord(word)\n# param_2 = obj.search(word)","hash":"1de3daee403446426c9e7a1dc027f98a2f4ebcf087d71bb31dfc562bb2d90796","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Add and Search Word - 01.py"}]}],"sources":["solutions"]},"topic-addandsearchword02":{"key":"topic-addandsearchword02","number":null,"title":"Add and Search Word 02","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add and Search Word - 02.py","code":"class TrieNode:\n    \n    def __init__(self):\n        self.childNodes = {}\n        self.isEnd = False\n\nclass WordDictionary:\n\n    def __init__(self):\n        self.root = TrieNode()\n\n    def addWord(self, word: str) -> None:\n        node = self.root\n        for c in word:\n            if node.childNodes.get(c) == None:\n                node.childNodes[c] = TrieNode()\n            node = node.childNodes.get(c)\n        node.isEnd = True\n\n    def search(self, word: str) -> bool:\n        def searchInNode(word, node) -> bool:\n            for i, c in enumerate(word):\n                if node.childNodes.get(c) == None:\n                    if c == '.':\n                        for x in node.childNodes:\n                            if searchInNode(word[i+1:], node.childNodes.get(x)):\n                                return True\n                    return False\n                else:\n                    node = node.childNodes.get(c)\n            return node.isEnd\n        return searchInNode(word, self.root)\n\n# Your WordDictionary object will be instantiated and called as such:\n# obj = WordDictionary()\n# obj.addWord(word)\n# param_2 = obj.search(word)","hash":"a5a17146e5759a5142c8cec0ca7539a0616f9914b8f2cd9a6fa2593748f68804","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Add and Search Word - 02.py"}]}],"sources":["solutions"]},"topic-addandsearchworddatastructuredesign":{"key":"topic-addandsearchworddatastructuredesign","number":null,"title":"Add and Search Word Data structure design","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add and Search Word - Data structure design.py","code":"class TrieNode:\n    \n    def __init__(self):\n        self.childNodes = {}\n        self.isEnd = False\n\nclass WordDictionary:\n\n    def __init__(self):\n        self.root = TrieNode()\n\n    def addWord(self, word: str) -> None:\n        node = self.root\n        for c in word:\n            node = node.childNodes.setdefault(c, TrieNode())\n        node.isEnd = True\n\n    def search(self, word: str) -> bool:\n        def searchInNode(word, node) -> bool:\n            for i, c in enumerate(word):\n                if node.childNodes.get(c) == None:\n                    if c == '.':\n                        for x in node.childNodes:\n                            if searchInNode(word[i+1:], node.childNodes.get(x)):\n                                return True\n                    return False\n                else:\n                    node = node.childNodes.get(c)\n            return node.isEnd\n        return searchInNode(word, self.root)\n\n# Your WordDictionary object will be instantiated and called as such:\n# obj = WordDictionary()\n# obj.addWord(word)\n# param_2 = obj.search(word)","hash":"a3755f70a8528b485c04937fa8934f9b2e7a829a5b9e45fe8fc929b25e0eb6fb","origins":[{"source":"solutions","path":"Trie/Add and Search Word - Data structure design.py"}]}],"sources":["solutions"]},"topic-addboldtaginstring":{"key":"topic-addboldtaginstring","number":null,"title":"Add Bold Tag in String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add Bold Tag in String.py","code":"class Solution:\n    def addBoldTag(self, S: str, words: List[str]) -> str:\n        N = len(S)\n        mask = [False] * N\n        for i in range(N):\n            prefix = S[i:]\n            for word in words:\n                if prefix.startswith(word):\n                    for j in range(i, min(i + len(word), N)):\n                        mask[j] = True\n        ans = []\n        for incl, grp in itertools.groupby(zip(S, mask), lambda z: z[1]):\n            if incl: ans.append(\"<b>\")\n            ans.append(\"\".join(z[0] for z in grp))\n            if incl: ans.append(\"</b>\")\n        return \"\".join(ans)","hash":"6e12965af07dc168e32c601965602784d5517cf7a73a4b3a55508c6b25af06ec","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 12/Add Bold Tag in String.py"}]}],"sources":["solutions"]},"topic-addstrings":{"key":"topic-addstrings","number":null,"title":"Add Strings","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add Strings.py","code":"class Solution:\n    def addStrings(self, num1: str, num2: str) -> str:\n        result, carry = [], 0\n        p1, p2 = len(num1) - 1, len(num2) - 1\n        while p1 >= 0 or p2 >= 0:\n            x1 = int(num1[p1]) if p1 >= 0 else 0\n            x2 = int(num2[p2]) if p2 >= 0 else 0\n            currentSum = x1 + x2 + carry\n            carry = currentSum // 10\n            result.insert(0, str(currentSum % 10))\n            p1 -= 1\n            p2 -= 1\n        if carry:\n            result.insert(0, str(carry))\n        return ''.join(result)","hash":"944a391f2ba142a7bf5b6dab3208669e3f4e28dbc71d0f5d398c7f5031506149","origins":[{"source":"solutions","path":"Add Strings.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Add Strings.py"}]}],"sources":["solutions"]},"topic-addtoarrayformofintegers":{"key":"topic-addtoarrayformofintegers","number":null,"title":"Add to Array Form of Integers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add to Array-Form of Integers.py","code":"class Solution:\n    def addToArrayForm(self, A: List[int], K: int) -> List[int]:\n        A[-1] += K\n        carry = 0\n        for i in range(len(A) - 1, -1, -1):\n            carry, A[i] = divmod(A[i], 10)\n            if i != 0:\n                A[i - 1] += carry\n        if carry:\n            A = list(map(int, str(carry))) + A\n        return A","hash":"666579401bc98b903a5d3968ec5f306c8b1227f40b4258a891dff21a60f24b11","origins":[{"source":"solutions","path":"Add to Array-Form of Integers.py"}]}],"sources":["solutions"]},"topic-addtwopolynomialsrepresentedaslinkedlists":{"key":"topic-addtwopolynomialsrepresentedaslinkedlists","number":null,"title":"Add Two Polynomials Represented as Linked Lists","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Add Two Polynomials Represented as Linked Lists.py","code":"# Definition for polynomial singly-linked list.\n# class PolyNode:\n#     def __init__(self, x=0, y=0, next=None):\n#         self.coefficient = x\n#         self.power = y\n#         self.next = next\n\nclass Solution:\n    def addPoly(self, poly1: 'PolyNode', poly2: 'PolyNode') -> 'PolyNode':\n        dummyHead = PolyNode()\n        current = dummyHead\n        while poly1 or poly2:\n            x1 = poly1.coefficient if poly1 is not None else 0\n            y1 = poly1.power if poly1 is not None else 0\n            x2 = poly2.coefficient if poly2 is not None else 0\n            y2 = poly2.power if poly2 is not None else 0\n            if y1 == y2:\n                val = x1 + x2\n                if val != 0:\n                    current.next = PolyNode(x = val, y = y1)\n                    current = current.next\n                poly1 = poly1.next if poly1 is not None else None\n                poly2 = poly2.next if poly2 is not None else None\n            elif y1 > y2:\n                val = x1\n                if val != 0:\n                    current.next = PolyNode(x = val, y = y1)\n                    current = current.next\n                poly1 = poly1.next if poly1 is not None else None\n            else:\n                val = x2\n                if val != 0:\n                    current.next = PolyNode(x = val, y = y2)\n                    current = current.next\n                poly2 = poly2.next if poly2 is not None else None\n        return dummyHead.next","hash":"df9cfe678ad810c52c28be496a0bbb4f721a0bcc05a14dce7279268decd6cac2","origins":[{"source":"solutions","path":"Add Two Polynomials Represented as Linked Lists.py"}]}],"sources":["solutions"]},"topic-advantageshuffle":{"key":"topic-advantageshuffle","number":null,"title":"Advantage Shuffle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Advantage Shuffle.py","code":"class Solution:\n    def advantageCount(self, A: List[int], B: List[int]) -> List[int]:\n        sortedA, sortedB = sorted(A), sorted(B)\n        assigned = {b: [] for b in B}\n        remaining = []\n        j = 0\n        for a in sortedA:\n            if a > sortedB[j]:\n                assigned[sortedB[j]].append(a)\n                j += 1\n            else:\n                remaining.append(a)\n        return [assigned[b].pop() if assigned[b] else remaining.pop() for b in B]","hash":"e6c92c7aa912ea74602fe85055341a042d4cb9f2c7e0efc82b7f31790f15e6ce","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Advantage Shuffle.py"}]}],"sources":["solutions"]},"topic-airplaneseatassignmentprobability":{"key":"topic-airplaneseatassignmentprobability","number":null,"title":"Airplane Seat Assignment Probability","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Airplane Seat Assignment Probability.py","code":"class Solution:\n    def nthPersonGetsNthSeat(self, n: int) -> float:\n        return 0.5 if n > 1 else 1","hash":"afabf5501088d2dab8abb0fbd9c31921af95c4f13a64a4160c24a30d76bc42c9","origins":[{"source":"solutions","path":"Airplane Seat Assignment Probability.py"}]}],"sources":["solutions"]},"topic-alertusingsamekeycardthreeormoretimesinaonehourperiod":{"key":"topic-alertusingsamekeycardthreeormoretimesinaonehourperiod","number":null,"title":"Alert Using Same Key Card Three or More Times in a One Hour Period","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Alert Using Same Key-Card Three or More Times in a One Hour Period.py","code":"class Solution:\n    def alertNames(self, keyName: List[str], keyTime: List[str]) -> List[str]:\n        graph, result = defaultdict(list), []\n        timeInSeconds = lambda x : int(x[0:2]) * 3600 + int(x[3:]) * 60\n        for name, time in zip(keyName, keyTime):\n            graph[name].append(timeInSeconds(time))\n        for name in sorted(graph.keys()):\n            start, count, times = 0, 0, sorted(graph[name])\n            for end in range(len(times)):\n                count += 1\n                while abs(times[end] - times[start]) > 3600 and end >= start:\n                    count -= 1\n                    start += 1\n                if count == 3:\n                    result.append(name)\n                    break\n        return result","hash":"26034fe2f26a3bf096bc300d2f49558d6f15c7c4f927a32534f7d9aae4e905b3","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 36/Alert Using Same Key-Card Three or More Times in a One Hour Period.py"}]}],"sources":["solutions"]},"topic-allelementsintwobinarysearchtrees":{"key":"topic-allelementsintwobinarysearchtrees","number":null,"title":"All Elements in Two Binary Search Trees","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"All Elements in Two Binary Search Trees.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def getAllElements(self, root1: TreeNode, root2: TreeNode) -> List[int]:\n        result, stack1, stack2 = [], deque(), deque()\n        while root1 or root2 or stack1 or stack2:\n            while root1:\n                stack1.append(root1)\n                root1 = root1.left\n            while root2:\n                stack2.append(root2)\n                root2 = root2.left\n            if not stack2 or stack1 and stack1[-1].val <= stack2[-1].val:\n                root1 = stack1.pop()\n                result.append(root1.val)\n                root1 = root1.right\n            else:\n                root2 = stack2.pop()\n                result.append(root2.val)\n                root2 = root2.right\n        return result","hash":"49b68e640aef6140cc2602679f14c4c3941b396dc46c15a14ade2329bea405bc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/All Elements in Two Binary Search Trees.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/All Elements in Two Binary Search Trees.py"}]}],"sources":["solutions"]},"topic-alloonedatastructure":{"key":"topic-alloonedatastructure","number":null,"title":"All O`one Data Structure","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"All O`one Data Structure.py","code":"class Node:\n    def __init__(self, count: int, key: str):\n        self.count = count\n        self.next, self.prev = None, None\n        self.words = set()\n        self.words.add(key)\n\nclass AllOne:\n\n    def __init__(self):\n        self.hashMap = defaultdict(Node)\n        self.head = Node(-1, \"\")\n        self.tail = Node(-1, \"\")\n        self.head.next, self.tail.prev = self.tail, self.head\n    \n    def _addNode(self, prevNode: Node, newNode: Node, nextNode: Node) -> None:\n        prevNode.next, nextNode.prev, newNode.prev, newNode.next = newNode, newNode, prevNode, nextNode\n    \n    def _removeNode(self, node: Node) -> None:\n        node.prev.next, node.next.prev = node.next, node.prev\n\n    def inc(self, key: str) -> None:\n        if key not in self.hashMap:\n            if self.head.next.count == 1:\n                self.hashMap[key] = self.head.next\n                self.head.next.words.add(key)\n            else:\n                newNode = Node(1, key)\n                self._addNode(self.head, newNode, self.head.next)\n                self.hashMap[key] = newNode\n        else:\n            node = self.hashMap[key]\n            node.words.remove(key)\n            if node.next.count == node.count + 1:\n                node.next.words.add(key)\n                self.hashMap[key] = node.next\n            else:\n                newNode = Node(node.count + 1, key)\n                self._addNode(node, newNode, node.next)\n                self.hashMap[key] = newNode\n            if len(node.words) == 0:\n                self._removeNode(node)\n\n    def dec(self, key: str) -> None:\n        node = self.hashMap[key]\n        node.words.remove(key)\n        if node.prev.count == node.count - 1:\n            node.prev.words.add(key)\n            self.hashMap[key] = node.prev\n        elif node.count - 1 > 0:\n            newNode = Node(node.count - 1, key)\n            self._addNode(node.prev, newNode, node)\n            self.hashMap[key] = newNode\n        else:\n            del self.hashMap[key]\n        if len(node.words) == 0:\n            self._removeNode(node)\n\n    def getMaxKey(self) -> str:\n        for word in self.tail.prev.words:\n            return word\n\n    def getMinKey(self) -> str:\n        for word in self.head.next.words:\n            return word\n\n\n# Your AllOne object will be instantiated and called as such:\n# obj = AllOne()\n# obj.inc(key)\n# obj.dec(key)\n# param_3 = obj.getMaxKey()\n# param_4 = obj.getMinKey()","hash":"51c6abfa18f2825d96988125e651ed68aa971f28cfbcb712eac599445c42bb80","origins":[{"source":"solutions","path":"All O`one Data Structure.py"}]}],"sources":["solutions"]},"topic-allpathsfromsourceleadtodestination":{"key":"topic-allpathsfromsourceleadtodestination","number":null,"title":"All Paths from Source Lead to Destination","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"All Paths from Source Lead to Destination.py","code":"class Solution:\n    def leadsToDestination(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:\n        WHITE, GRAY, BLACK = 0, 1, 2\n        def buildDigraph():\n            graph = [[] for _ in range(n)]\n            for src, dst in edges:\n                graph[src].append(dst)\n            return graph\n        def dfsHelper(node, states):\n            if states[node] != WHITE:\n                return states[node] == BLACK\n            if len(graph[node]) == 0:\n                return node == destination\n            states[node] = GRAY\n            for nextNode in graph[node]:\n                if not dfsHelper(nextNode, states):\n                    return False\n            states[node] = BLACK\n            return True\n        graph = buildDigraph()\n        return dfsHelper(source, [WHITE] * n)","hash":"67290ac093d066e3032ab850e52e25357c7be784f11c730da9f7dc132ccb9c76","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-06 Leetcoding Challenge/All Paths from Source Lead to Destination.py"}]}],"sources":["solutions"]},"topic-allpathsfromsourcetotarget":{"key":"topic-allpathsfromsourcetotarget","number":null,"title":"All Paths From Source to Target","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"All Paths From Source to Target.py","code":"class Solution:\n    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:\n        result = []\n        def dfs(node, currentPath):\n            if node == len(graph) - 1:\n                result.append(currentPath[:])\n                return\n            for neighbour in graph[node]:\n                dfs(neighbour, currentPath + [neighbour])\n        dfs(0, [0])\n        return result","hash":"24cdcbab9538a171683132f79e33b1f8941dd03e6a268cda7f7ef4dc6c857e6f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/All Paths From Source to Target.py"}]}],"sources":["solutions"]},"topic-ambiguouscoordinates":{"key":"topic-ambiguouscoordinates","number":null,"title":"Ambiguous Coordinates","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Ambiguous Coordinates.py","code":"class Solution:\n    def ambiguousCoordinates(self, s: str) -> List[str]:\n        def make(frag):\n            N = len(frag)\n            for d in range(1, N + 1):\n                left, right = frag[:d], frag[d:]\n                if ((not left.startswith('0') or left == '0') and (not right.endswith('0'))):\n                    yield left + ('.' if d != N else '') + right\n        S = s[1: -1]\n        return [\"({}, {})\".format(*cand) for i in range(1, len(S)) for cand in itertools.product(make(S[:i]), make(S[i:]))]","hash":"18a421f0a36f4984ea05cb03b1ac9068814d31603c007defb3cda187fa9f40a7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/Ambiguous Coordinates.py"}]}],"sources":["solutions"]},"topic-anglebetweenhandsofaclock":{"key":"topic-anglebetweenhandsofaclock","number":null,"title":"Angle Between Hands of a Clock","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Angle Between Hands of a Clock.py","code":"class Solution:\n    def angleClock(self, hour: int, minutes: int) -> float:\n        hourAngle = ((hour % 12) + (minutes / 60)) * 30\n        minuteAngle = (minutes % 60) * 6\n        diff = abs(hourAngle - minuteAngle)\n        return min(diff, 360 - diff)","hash":"5b80bfbebbfc9871b6de3b7be5c6f29b8b670ef582f4e37eac3a01300a35b790","origins":[{"source":"solutions","path":"Angle Between Hands of a Clock.py"}]}],"sources":["solutions"]},"topic-arithmeticslices":{"key":"topic-arithmeticslices","number":null,"title":"Arithmetic Slices","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Arithmetic Slices.py","code":"class Solution:\n    def numberOfArithmeticSlices(self, A: List[int]) -> int:\n        count, currentSum = 0, 0\n        for i in range(2, len(A)):\n            if A[i] - A[i - 1] == A[i - 1] - A[i - 2]:\n                count += 1\n            else:\n                currentSum += ((count + 1) * count) // 2\n                count = 0\n        currentSum += ((count + 1) * count) // 2\n        return currentSum","hash":"b23a090f651e8b0113989dbc5c1163f4001bdca2f51b206deab9d3b5039d0f9f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Arithmetic Slices.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Arithmetic Slices.py"}]}],"sources":["solutions"]},"topic-arithmeticsubarraysusingheap":{"key":"topic-arithmeticsubarraysusingheap","number":null,"title":"Arithmetic Subarrays Using heap","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Arithmetic Subarrays - Using heap.py","code":"class Solution:\n    def checkArithmeticSubarrays(self, nums: List[int], l: List[int], r: List[int]) -> List[bool]:\n        result = []\n        for left, right in zip(l, r):\n            subArray = nums[left : (right + 1)]\n            if len(subArray) == 1:\n                result.append(True)\n                continue\n            heapify(subArray)\n            b = heappop(subArray)\n            a = heappop(subArray)\n            diff = a - b\n            tempResult = True\n            while subArray:\n                b = a\n                a = heappop(subArray)\n                if a - b != diff:\n                    tempResult = False\n                    break\n            result.append(tempResult)\n        return result","hash":"2a98101b13d1fea041f424d31fe620fe8e698d99361e49fa05f6f6a094a1996a","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 212/Arithmetic Subarrays - Using heap.py"}]}],"sources":["solutions"]},"topic-arithmeticsubarraysusingsort":{"key":"topic-arithmeticsubarraysusingsort","number":null,"title":"Arithmetic Subarrays Using sort","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Arithmetic Subarrays - Using sort.py","code":"class Solution:\n    def checkArithmeticSubarrays(self, nums: List[int], l: List[int], r: List[int]) -> List[bool]:\n        result = []\n        for left, right in zip(l, r):\n            subArray = nums[left : (right + 1)]\n            if len(subArray) == 1:\n                result.append(True)\n                continue\n            subArray.sort()\n            diff, tempResult = subArray[1] - subArray[0], True\n            for i in range(2, len(subArray)):\n                if subArray[i] - subArray[i - 1] != diff:\n                    tempResult = False\n                    break\n            result.append(tempResult)\n        return result","hash":"e0191e9624481854537c5a33f56abb8d464d834a900f66e980def7459e835626","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 212/Arithmetic Subarrays - Using sort.py"}]}],"sources":["solutions"]},"topic-armstrongnumber":{"key":"topic-armstrongnumber","number":null,"title":"Armstrong Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Armstrong Number.py","code":"class Solution:\n    def isArmstrong(self, n: int) -> bool:\n        length = math.floor(math.log10(n)) + 1\n        def sumOfKthPowerOfDigits(n: int, k: int) -> int:\n            result = 0\n            while n != 0:\n                result += (n % 10) ** k\n                n //= 10\n            return result\n        return sumOfKthPowerOfDigits(n, length) == n","hash":"4658e1d22cd8f5ec04b1b83dc89b11e9996b364ecf1d33e81f17bab5e5a1b6f0","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-06 Leetcoding Challenge/Armstrong Number.py"}]}],"sources":["solutions"]},"topic-arrangingcoinsbinarysearch":{"key":"topic-arrangingcoinsbinarysearch","number":null,"title":"Arranging Coins Binary Search","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Arranging Coins - Binary Search.py","code":"class Solution:\n    def arrangeCoins(self, n: int) -> int:\n        start, end = 0, n\n        while start <= end:\n            mid = start + ((end - start) >> 1)\n            currentSum = (mid * (mid + 1)) >> 1\n            if currentSum == n:\n                return mid\n            elif currentSum > n:\n                end = mid - 1\n            else:\n                start = mid + 1\n        return end","hash":"ae323bba0e924f6fada5c4e8f002f94b962aa3acb0184404c4059cafc35f42dc","origins":[{"source":"solutions","path":"Arranging Coins - Binary Search.py"}]}],"sources":["solutions"]},"topic-arrangingcoinsmath":{"key":"topic-arrangingcoinsmath","number":null,"title":"Arranging Coins Math","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Arranging Coins - Math.py","code":"class Solution:\n    def arrangeCoins(self, n: int) -> int:\n        return (int)((2 * n + 0.25)**0.5 - 0.5)","hash":"0812b78d3df8ec431f5cf772be687c9d7915c03adef0ba91282cb149a95de1c4","origins":[{"source":"solutions","path":"Arranging Coins - Math.py"}]}],"sources":["solutions"]},"topic-arraynesting":{"key":"topic-arraynesting","number":null,"title":"Array Nesting","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Array Nesting.py","code":"class Solution:\n    def arrayNesting(self, nums: List[int]) -> int:\n        result = 0\n        for i in range(len(nums)):\n            if nums[i] != -1:\n                start, count = nums[i], 0\n                while nums[start] != -1:\n                    temp = start\n                    start = nums[start]\n                    count += 1\n                    nums[temp] = -1\n                result = max(result, count)\n        return result","hash":"f77a783fb57b454601dd4784bd718845b2a9e0456afbd0f2b24efc835911fd34","origins":[{"source":"solutions","path":"Array Nesting.py"}]}],"sources":["solutions"]},"topic-arrayofdoubledpairs":{"key":"topic-arrayofdoubledpairs","number":null,"title":"Array of Doubled Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Array of Doubled Pairs.py","code":"class Solution:\n    def canReorderDoubled(self, arr: List[int]) -> bool:\n        freqMap = Counter(arr)\n        for x in sorted(arr, key = abs):\n            if freqMap[x] == 0:\n                continue\n            if freqMap[2 * x] == 0:\n                return False\n            freqMap[x], freqMap[2 * x] = freqMap[x] - 1, freqMap[2 * x] - 1\n        return True","hash":"f3fbd3fbace8c843ec0db34fe0ce011e48c30d295ae7d464e08b130b65231320","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Array of Doubled Pairs.py"}]}],"sources":["solutions"]},"topic-arraypartitioni":{"key":"topic-arraypartitioni","number":null,"title":"Array Partition I","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Array Partition I.py","code":"class Solution:\n    def arrayPairSum(self, nums: List[int]) -> int:\n        nums.sort()\n        return sum(nums[i] for i in range(len(nums)) if i % 2 == 0)","hash":"5984805b61f110b7c30b5bc0740ebf81caba36e06af26953e892942056c1b0f5","origins":[{"source":"solutions","path":"Array Partition I.py"}]}],"sources":["solutions"]},"topic-arraywrapper":{"key":"topic-arraywrapper","number":null,"title":"Array Wrapper","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"javascript","name":"Array Wrapper.js","code":"/**\n * @param {number[]} nums\n */\nvar ArrayWrapper = function(nums) {\n    this.nums = nums;\n};\n\nArrayWrapper.prototype.valueOf = function() {\n    return this.nums.reduce((acc, num) => acc + num, 0);\n}\n\nArrayWrapper.prototype.toString = function() {\n    return \"[\" + this.nums.toString() + \"]\";\n}\n\n/**\n * const obj1 = new ArrayWrapper([1,2]);\n * const obj2 = new ArrayWrapper([3,4]);\n * obj1 + obj2; // 10\n * String(obj1); // \"[1,2]\"\n * String(obj2); // \"[3,4]\"\n */","hash":"79137f6e07f9e74c6ac3c6128b71059095dda36d35c3f49d4b318dc247c00c35","origins":[{"source":"solutions","path":"Array Wrapper.js"}]}],"sources":["solutions"]},"topic-asfarfromlandaspossible":{"key":"topic-asfarfromlandaspossible","number":null,"title":"As Far from Land as Possible","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"As Far from Land as Possible.py","code":"class Solution:\n    def maxDistance(self, grid: List[List[int]]) -> int:\n        DIRECTIONS = [(-1, 0), (1, 0), (0, 1), (0, -1)]\n        visited = set()\n        queue = deque([])\n        for i, row in enumerate(grid):\n            for j, cell in enumerate(row):\n                if cell == 1:\n                    queue.append((i, j))\n                    visited.add((i, j))\n        distance = -1\n        while queue:\n            queueSize = len(queue)\n            # Iterate over all the current cells in the queue.\n            while queueSize:\n                queueSize -= 1\n                landCell = queue.popleft()\n                # From the current land cell, traverse to all the four directions\n                # and check if it is a water cell. If yes, convert it to land\n                # and add it to the queue.\n                for direction in DIRECTIONS:\n                    x, y = landCell[0] + direction[0], landCell[1] + direction[1]\n                    if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and ((x, y) not in visited):\n                        # Marking as 1 to avoid re-iterating it.\n                        visited.add((x, y))\n                        queue.append((x, y))\n            distance += 1\n        return -1 if distance == 0 else distance","hash":"bc7a6b6425544f8b52d319339910afeb0bc9d546f0683c1e716f3677e63ec2c6","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-02 Leetcoding Challenge/As Far from Land as Possible.py"}]}],"sources":["solutions"]},"topic-backspacestringcompare":{"key":"topic-backspacestringcompare","number":null,"title":"Backspace String Compare","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Backspace String Compare.py","code":"class Solution:\n    def backspaceCompare(self, S: str, T: str) -> bool:\n        def trimmedString(S):\n            skip = 0\n            for x in S[::-1]:\n                if x == '#':\n                    skip += 1\n                elif skip:\n                    skip -= 1\n                else:\n                    yield x\n        return all(x == y for x, y in zip_longest(trimmedString(S), trimmedString(T)))","hash":"3214d4b95b4d9f0e543015d394a1b96460ad82fa391b80bf2081235bf919d9d5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Backspace String Compare.py"},{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 09/Backspace String Compare.py"}]}],"sources":["solutions"]},"topic-balanceabinarysearchtree":{"key":"topic-balanceabinarysearchtree","number":null,"title":"Balance a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Balance a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def balanceBST(self, root: TreeNode) -> TreeNode:\n        tempArray = []\n        def inorder(node: TreeNode):\n            if node:\n                inorder(node.left)\n                tempArray.append(node.val)\n                inorder(node.right)\n        inorder(root)\n        def constructTree(l: int, r: int):\n            if l < r:\n                m = l + ((r - l) >> 1)\n                return TreeNode(tempArray[m], constructTree(l, m), constructTree(m + 1, r))\n            return None\n        return constructTree(0, len(tempArray))","hash":"599ed012d15f5d4e1301803714b69232966d6e6c243cdbb978ac0109bb6eddd7","origins":[{"source":"solutions","path":"Balance a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-base7":{"key":"topic-base7","number":null,"title":"Base 7","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Base 7.py","code":"class Solution:\n    def convertToBase7(self, num: int) -> str:\n        if num == 0:\n            return '0'\n        negative = num < 0\n        num, result, chars = abs(num), [], '0123456'\n        while num > 0:\n            result.insert(0, chars[num % 7])\n            num //= 7\n        return ('-' if negative else '') + ''.join(result)","hash":"12592fc939811d3d4ec5c60aba8727f15777af021ab7dc36a219ab8dff23e61d","origins":[{"source":"solutions","path":"Base 7.py"}]}],"sources":["solutions"]},"topic-baseballgame":{"key":"topic-baseballgame","number":null,"title":"Baseball Game","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Baseball Game.py","code":"class Solution:\n    def calPoints(self, ops: List[str]) -> int:\n        scores, output, index = [], 0, -1\n        for op in ops:\n            if op == '+':\n                newScore = scores[index] + scores[index - 1]\n                scores.append(newScore)\n                index += 1\n                output += newScore\n            elif op == 'D':\n                newScore = scores[index] * 2\n                scores.append(newScore)\n                index += 1\n                output += newScore\n            elif op == 'C':\n                record = scores.pop()\n                index -= 1\n                output -= record\n            else:\n                scores.append(int(op))\n                index += 1\n                output += int(op)\n        return output","hash":"fc4c2a3847be4ccecc67c246717faaf4318d0f5efb93bdb1ee055e465287d693","origins":[{"source":"solutions","path":"Baseball Game.py"}]}],"sources":["solutions"]},"topic-basiccalculatorii":{"key":"topic-basiccalculatorii","number":null,"title":"Basic Calculator II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Basic Calculator II.py","code":"class Solution:\n    def calculate(self, s: str) -> int:\n        if len(s) == 0:\n            return 0\n        result, lastNumber, currentNumber, operation = 0, 0, 0, '+'\n        for i, char in enumerate(s):\n            if char.isdigit():\n                currentNumber = (currentNumber * 10) + int(char)\n            if not char.isdigit() and char != ' ' or i == len(s) - 1:\n                if operation == '+' or operation == '-':\n                    result += lastNumber\n                    lastNumber = currentNumber if operation == '+' else -1 * currentNumber\n                elif operation == '*':\n                    lastNumber *= currentNumber\n                elif operation == '/':\n                    lastNumber = int(lastNumber / currentNumber)\n                operation = char\n                currentNumber = 0\n        result += lastNumber\n        return result","hash":"4b20403700f6d21842cb3897792ac42bbc632b42d3c0a16ef31aca9e1bc2b4a3","origins":[{"source":"solutions","path":"Basic Calculator II.py"}]},{"language":"python","name":"Basic Calculator II.py","code":"# AddSub := MulDiv {[+-] MulDiv}\n# MulDiv := Unit {[*/] Unit}\n# Unit   := Integer | AddSub\n# Integer:= d+\n\nclass Solution:\n    def calculate(self, s: str) -> int:\n        queue = deque(s.replace(' ', '') + '$')\n        def addSub():\n            result = mulDiv()\n            while queue and queue[0] in ('+', '-'):\n                sign = queue.popleft()\n                if sign == '+':\n                    result += mulDiv()\n                elif sign == '-':\n                    result -= mulDiv()\n            return result\n        def mulDiv():\n            result = unit()\n            while queue and queue[0] in ('*', '/'):\n                sign = queue.popleft()\n                if sign == '*':\n                    result *= unit()\n                elif sign == '/':\n                    result = int(result/unit())\n            return result\n        def unit():\n            if queue[0].isdigit():\n                return integer()\n            else:\n                return addSub()\n        def integer():\n            result = []\n            while queue[0].isdigit():\n                result.append(queue.popleft())\n            return int(''.join(result))\n        return addSub()","hash":"1cbe3bb8e481281236a86fb02a124dd2820afd44c3dff0f3c9a69da6eb09d21f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Basic Calculator II.py"}]}],"sources":["solutions"]},"topic-basiccalculatoriii":{"key":"topic-basiccalculatoriii","number":null,"title":"Basic Calculator III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Basic Calculator III.py","code":"# BNF grammar\n# as := md {[+-] md}\n# md := unit {[*/] unit}\n# unit := integer | (as)\n# integer := d+\n\nclass Solution:\n    def calculate(self, s: str) -> int:\n        queue = deque(s.replace(' ', '') + '$')\n        def addSubtract():\n            result = multiplyDivide()\n            while queue[0] in ('+', '-'):\n                sign = queue.popleft()\n                if sign == '+':\n                    result = result + multiplyDivide()\n                else:\n                    result = result - multiplyDivide()\n            return result\n        def multiplyDivide():\n            result = unit()\n            while queue[0] in ('*', '/'):\n                sign = queue.popleft()\n                if sign == '*':\n                    result = result * unit()\n                else:\n                    result = int(result / unit())\n            return result\n        def unit():\n            if queue[0].isdigit():\n                return integer()\n            queue.popleft()\n            result = addSubtract()\n            queue.popleft()\n            return result\n        def integer():\n            result = []\n            while queue[0].isdigit():\n                result.append(queue.popleft())\n            return int(''.join(result))\n        return addSubtract()","hash":"f28af8ed6dcbf6aa86094d99cb1b9d83bcce52f858dffc62d3f3e14bd3bed6ec","origins":[{"source":"solutions","path":"Basic Calculator III.py"}]}],"sources":["solutions"]},"topic-beautifularrangement":{"key":"topic-beautifularrangement","number":null,"title":"Beautiful Arrangement","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Beautiful Arrangement.py","code":"class Solution:\n    def countArrangement(self, n: int) -> int:\n        count = 0\n        def swap(nums, i, j):\n            nums[i], nums[j] = nums[j], nums[i]\n        def permute(nums, currentIndex):\n            nonlocal count\n            if currentIndex == len(nums):\n                count += 1\n            for i in range(currentIndex, len(nums)):\n                swap(nums, i, currentIndex)\n                if nums[currentIndex] % (currentIndex + 1) == 0 or (currentIndex + 1) % nums[currentIndex] == 0:\n                    permute(nums, currentIndex + 1)\n                swap(nums, currentIndex, i)\n        nums = [i + 1 for i in range(n)]\n        permute(nums, 0)\n        return count","hash":"4bf429893a659ed2f2de4640f007f23b52fa5254ef927baaac64b5de95ad0968","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Beautiful Arrangement.py"}]}],"sources":["solutions"]},"topic-beautifularrangementii":{"key":"topic-beautifularrangementii","number":null,"title":"Beautiful Arrangement II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Beautiful Arrangement II.py","code":"class Solution:\n    def constructArray(self, n: int, k: int) -> List[int]:\n        result = list(range(1, n - k))\n        for i in range(k + 1):\n            if i % 2:\n                result.append(n - i // 2)\n            else:\n                result.append(n - k + i // 2)\n        return result","hash":"2957557f87b441d842cd2315d9f46077ec6d9655ab288668d659528265587c4e","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Beautiful Arrangement II.py"}]}],"sources":["solutions"]},"topic-beautifularray":{"key":"topic-beautifularray","number":null,"title":"Beautiful Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Beautiful Array.py","code":"class Solution:\n    def beautifulArray(self, n: int) -> List[int]:\n        memo = {1: [1]}\n        def recurse(n):\n            if n not in memo:\n                odds = recurse((n + 1) // 2)\n                evens = recurse(n // 2)\n                memo[n] = [2 * x - 1 for x in odds] + [2 * x for x in evens]\n            return memo[n]\n        return recurse(n)","hash":"0bd5b638d1d69b6ce93181f3591b0aea7e5f55c63327437b2b743e83c73e1c87","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Beautiful Array.py"}]}],"sources":["solutions"]}});
